let lo = 0, hi = n - 1;
while (lo <= hi) {
	const mid = (lo + hi) >> 1;
	if (a[mid] === x) return mid;
	if (a[mid] < x) lo = mid; // original: lo = mid + 1
	else hi = mid - 1;
}
return -1;

